const MAX_CHARS = 950;
const FIELD = 'output';

const items = $input.all();
const out = [];

const cpLen = (s) => Array.from(s).length;

function isInstagram(json) {
  const platform = String(json.platform || '').toLowerCase();
  const channel = String(json.channel || '');
  return platform === 'instagram' || channel === 'Channel::Instagram';
}

function cutSentences(paragraph, max) {
  if (cpLen(paragraph) <= max) return [paragraph];
  const parts = paragraph.split(/(?<=[.!?])\s+/);
  const res = [];
  let buf = '';
  for (const part of parts) {
    const cand = buf ? buf + ' ' + part : part;
    if (cpLen(cand) <= max) { buf = cand; continue; }
    if (buf) { res.push(buf); buf = ''; }
    let rest = part;
    while (cpLen(rest) > max) {
      res.push(Array.from(rest).slice(0, max).join(''));
      rest = Array.from(rest).slice(max).join('');
    }
    buf = rest;
  }
  if (buf) res.push(buf);
  return res;
}

function splitChunks(text, max) {
  if (cpLen(text) <= max) return [text];
  const chunks = [];
  let current = '';
  const flush = () => { const t = current.trim(); if (t) chunks.push(t); };
  for (const paragraph of text.split(/\n{2,}/)) {
    for (const piece of cutSentences(paragraph, max)) {
      const cand = current ? current + '\n\n' + piece : piece;
      if (cpLen(cand) <= max) { current = cand; }
      else { flush(); current = piece; }
    }
  }
  flush();
  return chunks.length ? chunks : [text];
}

for (const item of items) {
  const text = item.json[FIELD];
  if (typeof text === 'string' && isInstagram(item.json)) {
    for (const chunk of splitChunks(text, MAX_CHARS)) {
      out.push({ json: { ...item.json, [FIELD]: chunk } });
    }
  } else {
    out.push(item);
  }
}

return out;

